const analysis = $input.first().json.output;
const cfg = $('Set config').item.json;

if (!analysis) {
  throw new Error('Review analysis failed. Check your OpenAI credential.');
}

return [{
  json: {
    // Analysis output
    businessType: analysis.businessType || '',
    coreTransformation: analysis.coreTransformation || '',
    specificBenefit: analysis.specificBenefit || '',
    emotionalTone: analysis.emotionalTone || 'Satisfied',
    bestQuotablePhrase: analysis.bestQuotablePhrase || '',
    credibilitySignals: analysis.credibilitySignals || [],
    impliedPainSolved: analysis.impliedPainSolved || '',
    contentOpportunityScore: analysis.contentOpportunityScore || 5,
    isHighValue: (analysis.contentOpportunityScore || 5) >= 7,
    // Form data
    reviewText: cfg.reviewText,
    reviewerName: cfg.reviewerName,
    reviewerCompany: cfg.reviewerCompany,
    businessName: cfg.businessName,
    businessType_cfg: cfg.businessType,
    submittedBy: cfg.submittedBy,
    recipientEmail: cfg.recipientEmail,
    senderName: cfg.senderName,
    sheetId: cfg.sheetId,
    sheetName: cfg.sheetName,
    today: cfg.today
  }
}];
